if(!exists('build_bureau_features'))library(creditratingsystem)
# Independent small cash-income and evidence-state calculations.
local({
 date<-'2024-01-31';snapshot<-list(snapshot_id='s',release_seq=1,customer_id='c',provider_id='p',observed_at='2024-01-20',reported_at='2024-01-21',known_at='2024-01-22',coverage_status='COMPLETE',currency='EUR');line<-list(snapshot_id='s',snapshot_release_seq=1,tradeline_id='loan',opened_at='2023-01-01',closed_at=NULL,status='OPEN',balance=100,limit=200,max_dpd=0)
 mapping<-list(mapping_id='local',version='1',known_at='2023-01-01',snapshots=list(),tradelines=list(),inquiries=list());bureau<-function(snaps=list(snapshot),lines=list(line),queries=list(),max_age=30)build_bureau_features(snaps,lines,queries,mapping,'c','p',date,date,30,max_age,'EUR')
 r<-bureau();stopifnot(r$value$features$aggregate_open_utilization==.5,r$value$features$total_open_balance==100)
 revision<-snapshot;revision$release_seq<-2;revision$known_at<-'2024-02-01';new<-line;new$snapshot_release_seq<-2;new$balance<-999;closed<-line;closed$tradeline_id<-'old';closed$status<-'CLOSED';closed$closed_at<-'2024-01-10';closed$balance<-7;r<-bureau(list(snapshot,revision),list(line,new,closed));stopifnot(r$value$features$total_open_balance==100,r$value$features$known_closed_balance==7,r$value$features$reported_tradeline_count==2)
 query<-function(id,date,kind='HARD',known=date)list(inquiry_id=id,release_seq=1,customer_id='c',provider_id='p',occurred_at=date,known_at=known,kind=kind);f<-bureau(queries=list(query('excluded','2024-01-01'),query('hard','2024-01-02'),query('soft',date,'SOFT'),query('future','2024-01-03',known='2024-02-01')))$value$features;stopifnot(f$hard_inquiries==1,f$soft_inquiries==1)
 absent<-bureau(list(),list());nohit<-snapshot;nohit$coverage_status<-'NO_HIT';nohit<-bureau(list(nohit),list());stopifnot(is.null(absent$value$features$reported_tradeline_count),nohit$value$features$reported_tradeline_count==0,is.null(nohit$value$features$total_open_balance))
 profile<-list(profile_id='e',version='1',known_at='2023-01-01',minimum_tradelines=2,minimum_history_days=365,maximum_evidence_age_days=30,allow_partial_evidence=FALSE,feature_requirements=list(bureau_utilization=list('BUREAU'),cashflow=list('TRANSACTIONS')));thin<-function(b=bureau(),e=list(),p=profile)build_thin_file_features(b,e,p,'c',date,date)
 stopifnot(thin()$value$thin_file_stratum=='THIN',thin(absent)$value$thin_file_stratum=='BUREAU_ABSENT',thin(nohit)$value$thin_file_stratum=='BUREAU_NO_HIT',thin(bureau(max_age=1))$value$thin_file_stratum=='BUREAU_STALE')
 evidence<-list(evidence_id='tx',release_seq=1,known_at='2024-01-30',customer_id='c',evidence_type='TRANSACTIONS',observed_from='2023-01-01',observed_until='2024-01-29',coverage_status='COMPLETE');stopifnot(identical(thin(e=list(evidence))$value$supported_features,list('bureau_utilization','cashflow')));bad<-profile;bad$feature_requirements<-list(future_default=list('BUREAU'));stopifnot(inherits(tryCatch(thin(p=bad),error=function(e)e),'error'))
 row<-function(id,amount,component='salary',kind='SALARY')list(evidence_id=id,release_seq=1,known_at='2024-01-30',customer_id='c',component_id=component,component_type=kind,observed_from='2024-01-01',observed_until='2024-01-29',amount=amount,basis='NET',period='month',currency='EUR',evidence_reference='local document');policy<-list(policy_id='p',version='1',known_at='2023-01-01',source_priority=list('DOCUMENT','TRANSACTION','DECLARED'),included_component_types=list('SALARY','BONUS'),expected_component_ids=list('salary'),coverage_status='COMPLETE',maximum_age_days=30,allow_stale=FALSE,relative_discrepancy_threshold=.05);income<-function(declared=list(row('d',100)),docs=list(row('v',90)),transactions=list(row('t',95)),p=policy)reconcile_income_evidence(declared,docs,transactions,p,'c',date,date,'EUR','month','NET')
 r<-income(docs=list(row('v',90),row('bonus',10,'bonus','BONUS')))$value;stopifnot(r$total_selected_income==100,r$document_supported_current_income==100);salary<-r$components[[2]];stopifnot(salary$declared_difference== -10,salary$declared_relative_difference== -.1,salary$discrepancy_flag)
 gross<-row('v',900);gross$basis<-'GROSS';r<-income(docs=list(gross,row('sales',10000,'sales','BUSINESS_REVENUE')))$value;stopifnot(r$total_selected_income==95,r$document_supported_current_income==0)
 stale<-row('v',90);stale$observed_from<-'2023-10-01';stale$observed_until<-'2023-10-31';stale$known_at<-'2023-11-01';r<-income(list(),list(stale),list())$value;stopifnot(is.null(r$total_selected_income),r$known_selected_income==0,identical(r$missing_component_ids,list('salary')))
 p<-policy;p$expected_component_ids<-list('salary','rent');r<-income(p=p)$value;stopifnot(r$known_selected_income==90,is.null(r$total_selected_income))
})
